insert into setup_steps (path, phase, section, key, title, description, step_type, sort_order, is_optional, completed_by, resource_url) values
('custom', 'Getting Started', 'Setup & Payment', 'setup_initiation', 'Setup Initiation', 'Complete the intake form so we know your business and starting point.', 'form', 1, false, 'client', null),
('custom', 'Getting Started', 'Setup & Payment', 'setup_paid', 'Setup Paid', 'Payment received and your setup officially begins.', 'form', 2, false, 'staff', null),
('custom', 'Account Setup', 'Create a Game Plan', 'create_a_game_plan_decide_which_state_contract_y', 'Decide Which State/Contract You''ll Start With', 'Since every state and contract is so different, we recommend starting with your busiest state/contract, then following the steps for each additional state/contract to make sure nothing is missed.', 'form', 3, false, 'client', null),
('custom', 'Account Setup', 'Create a Game Plan', 'create_a_game_plan_decide_who_will_be_the_otc_gu', 'Decide Who Will Be the "OTC Guru (in training)"', 'The "OTC Guru (in training)" will most likely be someone who is in it for the long haul and is serious about the success of the business. They should have a vision for where OTC can take the business and be committed to the role as your team''s go-to for all things OTC. They should have in-depth knowledge of real estate transactions, contract/state expertise, an understanding of the correspondence tied to each step, a keen eye for detail, and a deep understanding of your specific processes and workflows. The important piece is choosing someone who knows your processes like the back of their hand.', 'form', 4, false, 'client', null),
('custom', 'Account Setup', 'Create a Game Plan', 'create_a_game_plan_decide_who_will_help_implemen', 'Decide Who Will Help Implement Your Data', 'Given that certain tasks are repetitive and already prepared by the OTC Guru (in training), it may be beneficial to delegate some implementation responsibilities to an assistant or virtual assistant (VA) who can efficiently follow step-by-step instructions.', 'form', 5, false, 'client', null),
('custom', 'Account Setup', 'Create a Game Plan', 'create_a_game_plan_otc_guru_in_training_time_blo', 'OTC Guru (in training) Time Block Checklist', 'Dedicate a minimum of 30 minutes each day for your OTC setup. Consistency is key, and allocating regular time ensures progress without overwhelming your team.', 'external_link', 6, true, 'client', 'https://docs.google.com/document/d/1V5YRGgKrf0e_VWJ_alu4J8q5gn2dXr-j5ZQikxy_Dko/copy'),
('custom', 'Account Setup', 'Create a Game Plan', 'create_a_game_plan_team_family_get_ready_email', 'Team & Family "Get Ready" Email', null, 'external_link', 7, true, 'client', 'https://docs.google.com/document/u/1/d/1ZbX_eR6EyzrZKdYvQv9HN52mFarbbQHmt57PNktMxkY/copy'),
('custom', 'Account Setup', 'Gather Your Custom Data', 'gather_your_custom_data_create_a_google_drive_se', 'Create a Google Drive/Setup Folder', 'To maintain a structured approach to data management, we recommend creating a dedicated Google Drive/shareable folder called "OTC Setup." This centralized location serves as the hub for storing, sharing, and managing all OTC migration-related data.', 'form', 8, false, 'client', null),
('custom', 'Account Setup', 'Gather Your Custom Data', 'gather_your_custom_data_create_organize_sub_fold', 'Create & Organize Sub-Folders', 'Sample sub-folders: Company Data, Contract Docs, Prep & Setup Sheets.', 'form', 9, false, 'client', null),
('custom', 'Account Setup', 'Gather Your Custom Data', 'gather_your_custom_data_a_copy_of_your_contract_', 'A Copy of Your Contract Docs', 'This includes any documents with information that is used throughout the transaction.', 'form', 10, false, 'client', null),
('custom', 'Account Setup', 'Gather Your Custom Data', 'gather_your_custom_data_an_exported_csv_spreadsh', 'An Exported CSV/Spreadsheet of Your Contacts', 'This is optional. You can manually add contacts as you go but if you have a large amount, it may be easier to import instead.', 'form', 11, true, 'client', null),
('custom', 'Account Setup', 'Gather Your Custom Data', 'gather_your_custom_data_a_list_of_compliance_ins', 'A List of Compliance/Inspection Documents', 'Gathering your Compliance/Inspection Docs will help when building Document Templates, as well as email and trigger automations.', 'form', 12, false, 'client', null),
('custom', 'Account Setup', 'Gather Your Custom Data', 'gather_your_custom_data_copies_of_your_email_tex', 'Copies of Your Email/Text Templates', 'There are plenty of sample email templates, but if you have your own, make a copy ready for updates.', 'form', 13, false, 'client', null),
('custom', 'Account Setup', 'Gather Your Custom Data', 'gather_your_custom_data_a_copy_of_your_current_i', 'A Copy of Your Current Intake Form', 'You can refer to your current form builder so that all conditional fields and field options are visible.', 'form', 14, false, 'client', null),
('custom', 'Account Setup', 'OTC Account Setup', 'otc_account_setup_otc_plan_pricing_comparison', '"OTC Plan & Pricing Comparison"', null, 'download', 15, true, 'client', 'https://docs.google.com/presentation/d/1Ual0Kt_t7wRC8X-tb3HdApkOOMXchzwqKt8I0SO814Y/view#slide=id.g25209b03486_0_183'),
('custom', 'Account Setup', 'OTC Account Setup', 'otc_account_setup_create_a_new_open_to_close_acc', 'Create a New Open to Close Account', 'OTC''s new setup structure may cut your setup time, so some may want to consider a brand new account. If you''ve had an OTC account for some time and don''t have anything you''d care to lose, we''d recommend starting from scratch.', 'form', 16, false, 'client', null),
('custom', 'Account Setup', 'OTC Account Setup', 'otc_account_setup_add_your_cell_phone_number_for', 'Add Your Cell Phone Number (for verification)', 'You will not receive the verification text otherwise.', 'form', 17, false, 'client', null),
('custom', 'Account Setup', 'OTC Account Setup', 'otc_account_setup_do_not_invite_team_or_create_a', 'Do Not Invite Team or Create a New Transaction', 'Team Members: we aren''t quite ready to add the team — prepare their setup before inviting them, so hold off until you''ve launched. New Transactions: since you only have 15 free transactions, hold off to get the most out of your trial — you''ll need them when we start our setup audit.', 'form', 18, false, 'client', null),
('custom', 'Account Setup', 'OTC Account Setup', 'otc_account_setup_explore_the_profile_security_b', 'Explore the Profile, Security, & Billing Dashboards', null, 'form', 19, false, 'client', null),
('custom', 'Account Setup', 'OTC Account Setup', 'otc_account_setup_explore_the_organizations_tabs', 'Explore the Organizations Tabs', null, 'form', 20, false, 'client', null),
('custom', 'Account Setup', 'OTC Account Setup', 'otc_account_setup_guide_to_adding_your_team', '"Guide to Adding Your Team"', null, 'form', 21, true, 'client', null),
('custom', 'Account Setup', 'Explore the OTC Interface', 'explore_the_otc_interface_toolbar_top_right', 'Toolbar (top right)', null, 'form', 22, false, 'client', null),
('custom', 'Account Setup', 'Explore the OTC Interface', 'explore_the_otc_interface_sidebar_left_column', 'Sidebar (left column)', null, 'form', 23, false, 'client', null),
('custom', 'Account Setup', 'Explore the OTC Interface', 'explore_the_otc_interface_bookmark_the_property_', 'Bookmark the Property Table', null, 'form', 24, false, 'client', null),
('custom', 'Account Setup', 'Explore the OTC Interface', 'explore_the_otc_interface_templating_hammer_icon', 'Templating (hammer icon)', null, 'form', 25, false, 'client', null),
('custom', 'Account Setup', 'Explore the OTC Interface', 'explore_the_otc_interface_settings_wheel_icon', 'Settings (wheel icon)', null, 'form', 26, false, 'client', null),
('custom', 'Account Setup', 'Explore the OTC Interface', 'explore_the_otc_interface_add_your_email_signatu', 'Add Your Email Signature(s)', 'IMPORTANT: the first email signature created acts as a default — if you have multiple signatures and one isn''t selected for a transaction, it defaults to the first one created. We''d recommend creating a generic signature with just your name and contact info first, then agent-specific signatures after, to avoid sending an email with another agent''s branded signature.', 'form', 27, false, 'client', null),
('custom', 'Account Setup', 'Explore the OTC Interface', 'explore_the_otc_interface_update_the_defaults_of', 'Update the Defaults of Your Global Settings', 'Trigger File Role Conditions — if NO, you must upload a document into the file role for the automation to work; if YES, only the File Role needs to be applied. File Sorting — you''ll want User Sorted Order. Broker Signed Button — this is a default document button; hide it if you don''t need to track the Broker Signature.', 'form', 28, false, 'client', null),
('custom', 'Account Setup', 'Explore the OTC Interface', 'explore_the_otc_interface_queued_properties_bott', 'Queued Properties (bottom left)', null, 'form', 29, false, 'client', null),
('custom', 'Account Setup', 'Explore the OTC Interface', 'explore_the_otc_interface_chat_help_button_botto', 'Chat/Help Button (bottom right)', null, 'form', 30, false, 'client', null),
('custom', 'Foundations', 'Workflow Fields', 'workflow_fields_download_the_prep_sheet_begin_yo', 'Download the Prep Sheet & Begin Your Edits', null, 'download', 31, true, 'client', 'https://tcoptimize.com/library/otcmembervault/lessons/01-workflow-fields-2/'),
('custom', 'Foundations', 'Workflow Fields', 'workflow_fields_understand_the_field_editor', 'Understand the Field Editor', 'Field Groups separate workflows for different parts of your business. Field Sections separate/organize your fields. Webhook Button lets you use fields in webhook integrations. Calendar Button automatically adds specific dates to your API calendar upon sync. Star Button controls which fields are visible to agent and client portal users. Inspector Button shows where a field is used across Email, Text, Smart Block, Task, Date, Field, and Intake Form Templates (Pro & Scale feature).', 'form', 32, false, 'client', null),
('custom', 'Foundations', 'Workflow Fields', 'workflow_fields_customize_your_otc_groups_sectio', 'Customize Your OTC Groups & Sections', 'Create the field groups and sections necessary for your setup. Add the field group "Archive" if it isn''t present.', 'form', 33, false, 'client', null),
('custom', 'Foundations', 'Workflow Fields', 'workflow_fields_understand_the_different_field_t', 'Understand the Different Field Types', 'Text (short text/words/numbers), Text Area (paragraphs with formatting), Decimal (currency/percentages), Date (usable in task templates as contingency dates), Number (days or longer string numbers), Choice (dropdown/radio options — dropdown is default but not ideal for intake form triggers; multiple select works in the intake form but needs a trigger per combination; radio button is best for 2 choices; stacked radio is best for more than 2).', 'form', 34, false, 'client', null),
('custom', 'Foundations', 'Workflow Fields', 'workflow_fields_delete_archive_unnecessary_field', 'Delete/Archive Unnecessary Fields', 'This will declutter and make your fields easier to find. System-required fields that cannot be deleted: Contract Status, Client Type, Address/City/State/Zip/County/Country, Contract Date, Closing Date.', 'form', 35, false, 'client', null),
('custom', 'Foundations', 'Workflow Fields', 'workflow_fields_add_rename_sort_organize_your_fi', 'Add, Rename, & Sort/Organize Your Fields', 'Use the Drag Bar to move fields within field sections. Use the field''s "Field Section" option to move fields between sections. Use the check boxes next to fields to move fields in bulk.', 'form', 36, false, 'client', null),
('custom', 'Foundations', 'Workflow Fields', 'workflow_fields_inactive_listing_contract_status', '"Inactive Listing" Contract Status', 'This is optional. The "Inactive Listing" Contract Status lets you change the status of a listing that''s gone under contract so you don''t lose your listing data if it falls out of contract.', 'form', 37, true, 'client', null),
('custom', 'Foundations', 'Workflow Fields', 'workflow_fields_understand_the_different_field_f', 'Understand the Different Field Features', 'Field Section, Visible, Field Label, Merge Field, Placeholder Text, Field Type, Table Background Color, Default Priority — plus some field-type-specific features like Choice Fields showing as Radio Buttons instead of a Dropdown.', 'form', 38, false, 'client', null),
('custom', 'Foundations', 'Workflow Fields', 'workflow_fields_update_your_field_s_features', 'Update Your Field''s Features', null, 'form', 39, false, 'client', null),
('custom', 'Foundations', 'Workflow Fields', 'workflow_fields_update_your_field_group_s_featur', 'Update Your Field Group''s Features', null, 'form', 40, false, 'client', null),
('custom', 'Foundations', 'Workflow Fields', 'workflow_fields_repeat_for_all_other_field_group', 'Repeat for All Other Field Groups', null, 'form', 41, false, 'client', null),
('custom', 'Foundations', 'Date Rule Calculations', 'date_rule_calculations_download_the_prep_sheet_b', 'Download the Prep Sheet & Begin Your Edits', null, 'download', 42, true, 'client', 'https://tcoptimize.com/library/otcmembervault/lessons/02-date-calculator/'),
('custom', 'Foundations', 'Date Rule Calculations', 'date_rule_calculations_customize_the_federal_hol', 'Customize the Federal Holidays Settings', 'You''re allowed up to 15 Federal Holidays. They can''t be conditioned, so working in multiple states may be problematic if holiday rules differ (e.g. if EM lands on a holiday, roll to Monday vs. Friday).', 'form', 43, false, 'client', null),
('custom', 'Foundations', 'Date Rule Calculations', 'date_rule_calculations_understand_the_date_templ', 'Understand the Date Templates', 'Number Field — a number entered here trumps the Date Template''s "Days" field. Count Days Using — choose Business Day(s), Calendar Day(s), or Calendar Day(s) - Skip Landing Weekend Day(s). Weekend/Federal Holiday Roll — control what happens if a day falls on a weekend or holiday. Skip Federal Holidays — control whether holidays are counted or skipped.', 'form', 44, false, 'client', null),
('custom', 'Foundations', 'Date Rule Calculations', 'date_rule_calculations_add_your_date_template_s_', 'Add Your Date Template(s) & Calculations', null, 'form', 45, false, 'client', null),
('custom', 'Foundations', 'Date Rule Calculations', 'date_rule_calculations_update_your_date_template', 'Update Your Date Template''s Features', null, 'form', 46, false, 'client', null),
('custom', 'Foundations', 'Contacts & Roles', 'contacts_roles_download_the_prep_sheet_begin_you', 'Download the Prep Sheet & Begin Your Edits', null, 'download', 47, true, 'client', 'https://tcoptimize.com/library/otcmembervault/lessons/03-contacts-roles-2/'),
('custom', 'Foundations', 'Contacts & Roles', 'contacts_roles_understand_contact_roles', 'Understand Contact Roles', 'Contact roles are shells for your contacts. "CC on All ..." roles: use these for assistants of a main contact role (e.g. use "CC on All Lender" for both a Lender Assistant and Loan Processor) to save time in TO/CC/BCC setup. Roles with "RBA" (Recommended By Agent): separating this from the non-RBA role lets you add agent-recommended companies in templates without mixing in the actual contact''s info. Connections let specific people auto-add to a transaction when the lead contact is added (e.g. a Title Rep''s assistant auto-added when the Title Rep is) — set this up via the contact''s Connections tab, search/add the assistant, then check "Add to Property."', 'form', 48, false, 'client', null),
('custom', 'Foundations', 'Contacts & Roles', 'contacts_roles_add_sort_your_contact_roles', 'Add & Sort Your Contact Roles', 'Contact Roles show in alphabetical and user-sorted order throughout the system.', 'form', 49, false, 'client', null),
('custom', 'Foundations', 'Contacts & Roles', 'contacts_roles_update_your_star_feature', 'Update Your Star Feature', null, 'form', 50, false, 'client', null),
('custom', 'Foundations', 'Contacts & Roles', 'contacts_roles_import_your_contacts_if_applicabl', 'Import Your Contacts (if applicable)', null, 'form', 51, false, 'client', null),
('custom', 'Foundations', 'Contacts & Roles', 'contacts_roles_understand_contact_tables', 'Understand Contact Tables', 'Side Panel — filter your data. Table Button — main tables. Segment Button — sub-tables.', 'form', 52, false, 'client', null),
('custom', 'Foundations', 'Contacts & Roles', 'contacts_roles_basic_contact_table_structure', '"Basic Contact Table Structure"', null, 'external_link', 53, true, 'client', 'https://docs.google.com/document/u/1/d/1D0OL8v3n8gEF6symJQF8nmKjqhr5j3Kt3t61E5rVcis/copy'),
('custom', 'Foundations', 'Contacts & Roles', 'contacts_roles_advanced_contact_table_structure', '"Advanced Contact Table Structure"', null, 'form', 54, false, 'client', null),
('custom', 'Foundations', 'Contacts & Roles', 'contacts_roles_create_your_contact_tables_segmen', 'Create Your Contact Tables & Segments', null, 'form', 55, false, 'client', null),
('custom', 'Foundations', 'Contacts & Roles', 'contacts_roles_create_contact_connections', 'Create Contact Connections', 'This is optional. Contact connections are definitely something you''ll want set up some day, but it isn''t necessary for the initial setup.', 'form', 56, true, 'client', null),
('custom', 'Foundations', 'Docs & Roles', 'docs_roles_download_the_prep_sheet_begin_your_ed', 'Download the Prep Sheet & Begin Your Edits', null, 'download', 57, true, 'client', 'https://tcoptimize.com/library/otcmembervault/lessons/04-docs-roles-2/'),
('custom', 'Foundations', 'Docs & Roles', 'docs_roles_understand_doc_roles_templates', 'Understand Doc Roles & Templates', 'File Roles automate your documents — apply them in email templates for automatic uploads and create Smart Blocks with conditions based on whether a file role "Exists" or is "Missing." Document Templates are shells with folders/placeholders for contract documents — create the template, then apply it to transactions (manually or via intake form triggers) to import documents into the right placeholders. Tip: name file roles so clients understand them (e.g. "Earnest Money Deposit" instead of "EMD"). Create separate document templates for conditional documents so you can trigger them only when they apply.', 'form', 58, false, 'client', null),
('custom', 'Foundations', 'Docs & Roles', 'docs_roles_add_your_doc_file_roles', 'Add Your Doc (File) Roles', null, 'form', 59, false, 'client', null),
('custom', 'Foundations', 'Docs & Roles', 'docs_roles_add_your_doc_templates', 'Add Your Doc Templates', null, 'form', 60, false, 'client', null),
('custom', 'Foundations', 'Docs & Roles', 'docs_roles_update_your_doc_features', 'Update Your Doc Features', 'Include the file role only if you selected NO in the Global Settings Defaults (see "Explore the OTC Interface").', 'form', 61, false, 'client', null),
('custom', 'Automations', 'Emails & Texts', 'emails_texts_download_the_prep_sheet_begin_your_', 'Download the Prep Sheet & Begin Your Edits', null, 'download', 62, true, 'client', 'https://tcoptimize.com/library/otcmembervault/lessons/05-emails-texts-templates-2/'),
('custom', 'Automations', 'Emails & Texts', 'emails_texts_import_your_emails_texts', 'Import Your Emails & Texts', null, 'form', 63, false, 'client', null),
('custom', 'Automations', 'Emails & Texts', 'emails_texts_clean_your_emails_texts', 'Clean Your Emails & Texts', null, 'form', 64, false, 'client', null),
('custom', 'Automations', 'Emails & Texts', 'emails_texts_understand_email_templates', 'Understand Email Templates', 'Email templates are saved emails you can reuse, with features like: designate TO/CC/BCC by contact role; prefill subject with merge fields; advanced formatting with images/emoji/links/GIFs; merge fields for workflow fields, contact roles, smart blocks, and OTC team info; pre-select documents/file roles to attach. Tips: keep template titles consistent (e.g. "B"/"S"/"L" prefixes for buyer/seller/listing); use TextCleanr.com when pasting from outside sources to avoid extra spaces; use the "CC on All..." roles in TO/CC/BCC as needed; set your Contract Title format (e.g. "Seller Last to Buyer Last // Address") so subject lines auto-include both last names; use the SB button to preview/edit Smart Block content inline.', 'form', 65, false, 'client', null),
('custom', 'Automations', 'Emails & Texts', 'emails_texts_add_your_custom_emails_if_not_impor', 'Add Your Custom Emails (if not imported)', null, 'form', 66, false, 'client', null),
('custom', 'Automations', 'Emails & Texts', 'emails_texts_clean_your_otc_custom_imported_emai', 'Clean Your OTC/Custom/Imported Emails', null, 'form', 67, false, 'client', null),
('custom', 'Automations', 'Emails & Texts', 'emails_texts_update_your_email_s_to_cc_bcc_docs', 'Update Your Email''s TO, CC, BCC, & Docs', null, 'form', 68, false, 'client', null),
('custom', 'Automations', 'Emails & Texts', 'emails_texts_understand_text_templates', 'Understand Text Templates', 'Text templates are saved text messages you can reuse and automate. Tips: inbound replies land in the Text Inbox without showing which transaction they''re about — add a note like "this is an automated message, please do not reply"; group texting isn''t available — messages to multiple parties send individually.', 'form', 69, false, 'client', null),
('custom', 'Automations', 'Emails & Texts', 'emails_texts_add_your_custom_texts_if_not_import', 'Add Your Custom Texts (if not imported)', null, 'form', 70, false, 'client', null),
('custom', 'Automations', 'Emails & Texts', 'emails_texts_clean_your_otc_custom_imported_text', 'Clean Your OTC/Custom/Imported Texts', null, 'form', 71, false, 'client', null),
('custom', 'Automations', 'Emails & Texts', 'emails_texts_update_your_text_s_to', 'Update Your Text''s TO', null, 'form', 72, false, 'client', null),
('custom', 'Automations', 'Emails & Texts', 'emails_texts_sort_organize_your_emails_texts', 'Sort & Organize Your Emails & Texts', 'Put them in an order that makes sense and create categories for quick reference.', 'form', 73, true, 'client', null),
('custom', 'Automations', 'Emails & Texts', 'emails_texts_confirm_your_twilio_connection', 'Confirm Your Twilio Connection', 'You''ll need to submit your business information to use texting. If you didn''t receive instructions or run into issues, reach out via the Chat/Help button or help@opentoclose.com.', 'form', 74, false, 'client', null),
('custom', 'Automations', 'Emails & Texts', 'emails_texts_create_confirm_your_twilio_number', 'Create/Confirm Your Twilio Number', 'Located in the Settings wheel, then Phone Numbers.', 'form', 75, false, 'client', null),
('custom', 'Automations', 'Smart Blocks & Groups', 'smart_blocks_groups_understand_smart_blocks_grou', 'Understand Smart Blocks & Groups', 'This is optional and unnecessary during the initial setup. View the Intake Form Training under "Group Coaching Replays" in the OTC Member Vault.', 'form', 76, true, 'client', null),
('custom', 'Automations', 'Smart Blocks & Groups', 'smart_blocks_groups_smart_block_your_intro_email', 'Smart Block Your Intro Emails', null, 'external_link', 77, true, 'client', 'https://tcoptimize.com/library/otcmembervault/lessons/smart-blocks-intros/'),
('custom', 'Automations', 'Smart Blocks & Groups', 'smart_blocks_groups_smart_block_your_status_repo', 'Smart Block Your Status Report Emails', null, 'external_link', 78, true, 'client', 'https://tcoptimize.com/library/otcmembervault/lessons/smart-blocks-status-update/'),
('custom', 'Automations', 'Smart Blocks & Groups', 'smart_blocks_groups_smart_block_emails_with_cond', 'Smart Block Emails with Conditional Verbiage', null, 'form', 79, true, 'client', null),
('custom', 'Automations', 'Task Templates', 'task_templates_download_the_prep_sheet_begin_you', 'Download the Prep Sheet & Begin Your Edits', null, 'download', 80, true, 'client', 'https://tcoptimize.com/library/otcmembervault/lessons/06-tasks-templates-2/'),
('custom', 'Automations', 'Task Templates', 'task_templates_import_your_task_templates', 'Import Your Task Templates', null, 'form', 81, false, 'client', null),
('custom', 'Automations', 'Task Templates', 'task_templates_understand_task_templates', 'Understand Task Templates', 'Task templates are lists of tasks completed for each transaction, applied manually, via intake form triggers, or via property template. Tips: plan in a Google Sheet before importing; use prefixes like "B"/"S"/"L" for buyer/seller/listing templates (e.g. "B - TRANSACTIONS"); create separate templates for conditional tasks so intake form triggers can apply them only when relevant.', 'form', 82, false, 'client', null),
('custom', 'Automations', 'Task Templates', 'task_templates_rename_your_task_templates_to_out', 'Rename Your Task Templates (to outline conditions)', null, 'form', 83, false, 'client', null),
('custom', 'Automations', 'Task Templates', 'task_templates_sort_organize_your_task_templates', 'Sort & Organize Your Task Templates', null, 'form', 84, false, 'client', null),
('custom', 'Automations', 'Task Templates', 'task_templates_update_your_task_s_features', 'Update Your Task''s Features', 'Take advantage of bulk actions — select the bubble next to each task with identical or similar settings to update in bulk.', 'form', 85, false, 'client', null),
('custom', 'Automations', 'Task Templates', 'task_templates_sort_organize_your_tasks', 'Sort & Organize Your Tasks', null, 'form', 86, false, 'client', null),
('custom', 'Automations', 'Intake Forms', 'intake_forms_re_visit_your_workflow_fields_prep_', 'Re-visit Your Workflow Fields Prep Sheet', null, 'form', 87, true, 'client', null),
('custom', 'Automations', 'Intake Forms', 'intake_forms_understand_basic_intake_forms', 'Understand Basic Intake Forms', 'A basic intake form lets you add transactions via the OTC form but does not include automations or form conditions.', 'form', 88, false, 'client', null),
('custom', 'Automations', 'Intake Forms', 'intake_forms_create_a_pending_buyer_intake_form', 'Create a Pending Buyer Intake Form', null, 'form', 89, false, 'client', null),
('custom', 'Automations', 'Intake Forms', 'intake_forms_update_your_settings', 'Update Your Settings', null, 'form', 90, false, 'client', null),
('custom', 'Automations', 'Intake Forms', 'intake_forms_update_your_agent_intake_fields', 'Update Your Agent Intake Fields', null, 'form', 91, false, 'client', null),
('custom', 'Automations', 'Intake Forms', 'intake_forms_update_your_internal_fields', 'Update Your Internal Fields', null, 'form', 92, false, 'client', null),
('custom', 'Automations', 'Intake Forms', 'intake_forms_update_your_internal_instructions', 'Update Your Internal Instructions', 'Update Defaults & Settings (down arrow next to "Property Details" → "Defaults & Settings"). Add General and Conditional Task Templates (Basic Intake Form). Add General and Conditional Document Templates (Basic Intake Form). Add Contacts (Buyer, Seller, Agent, Coop, Lender, Title/Attorney/Escrow). API Sync — click the "APIs" tab and select the right integration. Complete this task, approve the submission, then go to the "Tasks" tab to start the first task.', 'form', 93, false, 'client', null),
('custom', 'Automations', 'Intake Forms', 'intake_forms_update_your_layout', 'Update Your Layout', null, 'form', 94, false, 'client', null),
('custom', 'Automations', 'Intake Forms', 'intake_forms_click_secure_forms_submit_your_firs', 'Click "Secure Forms" & Submit Your First Intake', null, 'form', 95, false, 'client', null),
