-- Add phase/optional/resource-url metadata to setup_steps, and replace the
-- placeholder 10-item "custom" path checklist with the full ~137-item DIY
-- setup checklist (sourced from OTC_Setup_Checklist_Doc.docx), preserving
-- the two synthetic "Getting Started" items (setup_initiation, setup_paid)
-- that the app looks up by exact key.

alter table setup_steps add column if not exists is_optional boolean not null default false;
alter table setup_steps add column if not exists phase text;
alter table setup_steps add column if not exists resource_url text;

delete from setup_steps where path = 'custom';

